@@ -0,0 +1,7 @@
+export function sanitizeFilename(filename) {
+  let sanitized = filename.replace(/[<>:"|?*]/g, "-");
+  if (sanitized.trim() === "") {
+    return "_";
+  }
+  return sanitized;
+}

